bounded_host_request.command:
set -eu
docker exec -i debug-ai-debug-ai-1 node - <<'NODE'
const fs=require("node:fs"),p=require("node:path"),{decodeEnvelope}=require("/app/orchestrator/durable-primitives.js");
const rid="run_mwytb5d9_cf1d2b2ecd",base="/app/runtime/durable/durable";
const res=awaitable();
async function awaitable(){
 const r=await fetch("http://127.0.0.1:8787/v1/status/"+rid);const d=(await r.json()).durable;
 console.log("RUN",JSON.stringify({status:d.job_status,cursor:d.workflow_cursor,active:d.active_in_process,error:d.last_execution_error,invocations:d.role_invocations.map(x=>({role:x.role,phase:x.phase,elapsed_ms:x.elapsed_ms,failure_code:x.failure_code,telemetry:x.telemetry}))}));
 const w=p.join(base,"work-item",rid);
 if(fs.existsSync(w))for(const dir of fs.readdirSync(w)){const a=fs.readdirSync(p.join(w,dir)).sort();if(a.length){const r=decodeEnvelope(fs.readFileSync(p.join(w,dir,a.at(-1))),{expectedSchema:"role-work-item-continuation/v1"});console.log("CHECKPOINT",JSON.stringify({key:r.key,status:r.status,steps:r.steps,progress:r.progress,result:r.result,reason:r.reason}));}}
}
res.catch(e=>{console.error(e.name,e.message);process.exitCode=1});
NODE
